GimCorpus.put(134,0,[[1,1,"חֲזוֹן עֹבַדְיָה. מַאי שְׁנָא עֹבַדְיָה לֶאֱדוֹם וְלֹא נִיבָּא נְבוּאָה אַחֶרֶת? אָמְרוּ חֲכָמִים: עֹבַדְיָה גֵּר אֲדוֹמִי הָיָה. אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא: מֵהֶם וּבָהֶם אָבִיא עֲלֵיהֶם. יָבֹא עֹבַדְיָה שֶׁדָּר בֵּין שְׁנֵי רְשָׁעִים, אַחְאָב וְאִיזֶבֶל, וְלֹא לָמַד מִמַּעֲשֵׂיהֶם, וְיִפְרַע מֵעֵשָׂו הָרָשָׁע שֶׁדָּר בֵּין שְׁנֵי צַדִּיקִים, יִצְחָק וְרִבְקָה, וְלֹא לָמַד מִמַּעֲשֵׂיהֶם:",1,0],[1,2,"הִנֵּה קָטֹן נְתַתִּיךָ. כְּלַפֵּי שֶׁקְּרָאוֹ אָבִיו בְּנוֹ הַגָּדוֹל וְאִמּוֹ בְּנָהּ הַגָּדוֹל, אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא: לְפָנַי קָטֹן הוּא. רַבּוֹתֵינוּ דָּרְשׁוּ: קָטֹן - שֶׁלֹּא הָיָה לָהֶם לֹא כְּתָב וְלֹא לָשׁוֹן:",1,0],[1,2,"בָּזוּי. שֶׁלֹּא הָיוּ מַעֲמִידִין מֶלֶךְ בֶּן מֶלֶךְ:",2,0],[1,3,"שֹׁכְנִי בְחַגְוֵי סֶלַע. סוֹמֵךְ עַל מִשְׁעֶנֶת אֲבוֹתָיו אַבְרָהָם וְיִצְחָק, וְהֵם לֹא יוֹעִילוּ לוֹ. חַגְוֵי כְּמוֹ ״וְהָיְתָה אַדְמַת יְהוּדָה לְמִצְרַיִם לְחָגָּא״ (ישעיהו יט:יז), ברייטיינ״א בְּלַעַ״ז. וְאַל תִּתְמַהּ עַל וָי״ו שֶׁל חַגְוֵי שֶׁהִיא כְּוָי״ו שֶׁל קְצָוֵי (תהלים סה:ו) וּכְוָי״ו שֶׁל כִּמְטַחֲוֵי (בראשית כא:טז), שֶׁאֵין יְסוֹד בַּתֵּיבָה אֶלָּא טֵי״ת וְחֵי״ת:",1,0],[1,5,"בָּאוּ לְךָ. עָלֶיךָ:",1,0],[1,5,"אֵיךְ נִדְמֵיתָה. לָמָּה נִרְדַּמְתָּה דוּמָם עַד שֶׁגָּנְבוּ כָּל רְצוֹנָם:",2,0],[1,5,"הֲלֹא בּוֹצְרִים יַשְׁאִירוּ עוֹלֵלוֹת. וְאֵלֶּה לֹא יַשְׁאִירוּ לְךָ כְּלוּם, כִּי יַחְפְּשׂוּךָ וִיגַלּוּ וְיִדְרְשׁוּ מַצְפּוּנֶיךָ:",3,0],[1,6,"נִבְעוּ. תַּרְגּוּם יוֹנָתָן: אִיתְגַּלְיָין, וּלְשׁוֹן אֲרָמִית נִבְעוּ נִתְבַּקְּשׁוּ, וְכֵן ״אִם תִּבְעָיוּן בְּעָיוּ״ (ישעיהו כא:יב):",1,0],[1,7,"עַד הַגְּבוּל שִׁלְּחוּךָ. אוֹתָם שֶׁהִבְטִיחוּךָ לְעֶזְרָה בָּאוּ עִמְּךָ וְלִוּוּךָ עַד גְּבוּל אַרְצְךָ עַד הַסְּפָר, שֶׁשָּׁם בָּאוּ עָלֶיךָ לַמִּלְחָמָה, וּבְזֹאת הִשִּׂיאוּךָ וְהִצְלִיחוּ:",1,0],[1,7,"יָכְלוּ לְךָ. לְפַתּוֹתְךָ לָצֵאת וְשָׁבוּ מֵאַחֲרֶיךָ:",2,0],[1,7,"לַחְמְךָ יָשִׂימוּ מָזוֹר תַּחְתֶּיךָ. אַף מַאֲכָלְךָ שָׂם לְךָ אָחִיךָ יַעֲקֹב לְמָזוֹר, שֶׁנָּתַן לְךָ לֶחֶם וּנְזִיד עֲדָשִׁים וְעַל יָדוֹ בָּזִיתָ הַבְּכוֹרָה:",3,0],[1,7,"מָזוֹר. חֳלִי:",4,0],[1,9,"וְחַתּוּ גִבּוֹרֶיךָ תֵּימָן. יֵחַתּוּ וְיִפְחֲדוּ לָנוּס אֶל אֶרֶץ יִשְׁמָעֵאל. וְתַרְגּוּם יוֹנָתָן: וְיִתְבָּרוּן גִּבָּרָךְ יָתְבֵי אַרְעָא דְרוֹמָא:",1,0],[1,9,"לְמַעַן יִכָּרֶת. כָּל אִישׁ גִּבּוֹר:",2,0],[1,9,"מֵהַר עֵשָׂו מִקָּטֶל. מֵרוֹב הֶרֶג שֶׁיָּבֹא עֲלֵיכֶם:",3,0],[1,10,"מֵחֲמַס אָחִיךָ יַעֲקֹב. בִּשְׁבִיל חָמָס שֶׁעָשִׂיתָ לְיַעֲקֹב:",1,0],[1,11,"בְּיוֹם עֲמָדְךָ מִנֶּגֶד. שֶׁלֹּא בָאתָ לַעֲזוֹר לוֹ:",1,0],[1,11,"גַּם אַתָּה כְּאַחַד מֵהֶם. אַעֲלֶה אֲנִי עָלֶיךָ כְּאִלּוּ אַתָּה מִן הַבָּאִים עֲלֵיהֶם:",2,0],[1,12,"וְאַל תֵּרֶא בְיוֹם אָחִיךָ. לֹא הָיָה לְךָ לְהַבִּיט וְלַעֲמוֹד מִנֶּגֶד:",1,0],[1,12,"בְּיוֹם נָכְרוֹ. בְּיוֹם הִסְגִּירוֹ בְּיַד אוֹיֵב, הוּא הַבַּבְלִיִּים. וְכֵן הוּא אוֹמֵר בְּשָׁאוּל ״נִכַּר אֹתוֹ אֱלֹהִים בְּיָדִי״ (שמואל א כג:ז), הִסְגִּיר אוֹתוֹ בְּיָדִי:",2,0],[1,13,"וְאַל תִּשְׁלַחְנָה בְחֵילוֹ. אַל תִּשְׁלַחְנָה יָדְךָ בִּנְכָסָיו, כֵּן תִּרְגֵּם יוֹנָתָן. וּמִקְרָא קָצָר הוּא וְצָרִיךְ לְהוֹסִיף עָלָיו יָדְךָ:",1,0],[1,14,"וְאַל תַּעֲמֹד עַל הַפֶּרֶק. מָקוֹם שֶׁהַבּוֹרְחִים יוֹצְאִים דֶּרֶךְ שָׁם לִימָּלֵט, וּבִלְשׁוֹן לַעַ״ז קוֹרְאִים אוֹתוֹ טרו״ג:",1,0],[1,16,"כַּאֲשֶׁר שְׁתִיתֶם עַל הַר קָדְשִׁי. כְּמָה דַחֲדִיתוּן עַל מְחַת טוּרָא דְקוּדְשִׁי:",1,0],[1,16,"וְלָעוּ. כְּתַרְגּוּמוֹ: וְיִסְתַּלְעֲמוּן, לְשׁוֹן מְהוּמָה וְשִׁמָּמוֹן וְטֵרוּף דַּעַת, אישטורדישו״ן בְּלַעַ״ז:",2,0],[1,17,"אֵת מוֹרָשֵׁיהֶם. נִכְסֵי עַמְמַיָּא דַּהֲווֹ מַחְסְנִין לְהוֹן:",1,0],[1,18,"כִּי ה׳ דִּבֵּר. וְהֵיכָן דִּבֵּר? ״וְיֵרְדְּ מִיַּעֲקֹב וְהֶאֱבִיד שָׂרִיד וְגוֹ׳״ (במדבר כד:יט):",1,0],[1,19,"וְיָרְשׁוּ הַנֶּגֶב. יִשְׂרָאֵל שֶׁהָיוּ יוֹשְׁבִין בִּדְרוֹמָהּ שֶׁל אֶרֶץ יִשְׂרָאֵל יִירְשׁוּ אֶת הַר עֵשָׂו שֶׁהוּא בְּמֵצַר דָּרוֹם, וּבְנֵי הַשְּׁפֵלָה יִירְשׁוּ אֶת אֶרֶץ פְּלִשְׁתִּים וְאֶת הַר אֶפְרַיִם וְאֶת הַר שׁוֹמְרוֹן:",1,0],[1,19,"וּבִנְיָמִין אֶת הַגִּלְעָד. וּבְנֵי מְנַשֶּׁה שֶׁהָיְתָה אֶרֶץ גִּלְעָד שֶׁלָּהֶם יִפְשְׁטוּ לָהֶם מֵהַלְאָה לִגְבוּלוֹתֶיהָ שֶׁל אֶרֶץ יִשְׂרָאֵל בְּמִזְרָחָהּ:",2,0],[1,20,"וְגָלוּת הַחֵל הַזֶּה. תִּרְגֵּם יוֹנָתָן: עַמָּא הָדֵין. הַחֵל לְשׁוֹן חַיִל, כְּמוֹ ״וַיָּבֹא יְרוּשָׁלַיִם בְּחֵיל כָּבֵד״ (ישעיהו לו:ב) דְּרַבְשָׁקֵה, אֶלָּא שֶׁזֶּה חָסֵר יוֹ״ד. וְיֵשׁ עוֹד לְפָרֵשׁ הַחֵל הַזֶּה - גָּלוּת הַגַּיְא הַזֶּה:",1,0],[1,20,"לִבְנֵי יִשְׂרָאֵל אֲשֶׁר כְּנַעֲנִים עַד צָרְפַת. גָּלוּת אֲשֶׁר הוּא מִבְּנֵי יִשְׂרָאֵל שֶׁגָּלוּ מֵעֲשֶׂרֶת הַשְּׁבָטִים לְאֶרֶץ כְּנַעֲנִים עַד צָרְפַת:",2,0],[1,20,"וְגָלוּת יְרוּשָׁלַ͏ִם אֲשֶׁר בִּסְפָרַד. שֶׁהֵם מִבְּנֵי יְהוּדָה אֲשֶׁר גָּלוּ לִסְפָרַד, הֵם יִירְשׁוּ אֶת עָרֵי הַנֶּגֶב שֶׁבִּדְרוֹמָהּ שֶׁל אֶרֶץ יִשְׂרָאֵל. וְאוֹמְרִים הַפּוֹתְרִים: צָרְפַת הוּא הַמַּלְכוּת שֶׁקּוֹרִין פרנצ״א בְּלַעַ״ז. סְפָרַד תִּרְגֵּם יוֹנָתָן: אספמיא:",3,0],[1,21,"וְעָלוּ. שָׂרֵי יִשְׂרָאֵל מוֹשִׁיעִים בְּהַר צִיּוֹן:",1,0],[1,21,"לִשְׁפֹּט אֶת הַר עֵשָׂו. לִיפָּרַע מֵהַר עֵשָׂו אֲשֶׁר עָשׂוּ לְיִשְׂרָאֵל. לִשְׁפֹּט יושטיציי״ר בְּלַעַ״ז:",2,0],[1,21,"הַר עֵשָׂו. תַּרְגּוּם יוֹנָתָן: כַּרְכָּא רַבָּא דְעֵשָׂו:",3,0],[1,21,"וְהָיְתָה לַה׳ הַמְּלוּכָה. לִמֶּדְךָ שֶׁאֵין מַלְכוּתוֹ שְׁלֵימָה עַד שֶׁיִּפָּרַע מֵעֲמָלֵק:",4,0]]);
